// Command gen-catalog writes the static engine catalogue consumed by the frontend.
package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"

	"github.com/eventrouter/router/pkg/engine/catalog"
	"github.com/eventrouter/router/pkg/engine/compile"
)

// Output names the default generated files.
type Output string

const (
	DefaultJSONOutput Output = "web/src/api/generated/engineCatalog.json"
	DefaultTSOutput   Output = "web/src/api/generated/engineCatalog.ts"
	TSBanner          Output = "/* generated by cmd/gen-catalog, do not edit */\nimport type { EngineCatalog } from \"./engineCatalogTypes\";\n\nexport const engineCatalog: EngineCatalog = "
)

// FileMode of the generated file.
const FileMode os.FileMode = 0o644

func main() {
	out := flag.String("out", string(DefaultJSONOutput), "JSON output path")
	tsOut := flag.String("ts-out", string(DefaultTSOutput), "TypeScript module output path (empty to skip)")
	flag.Parse()
	if err := (Generator{Out: *out, TSOut: *tsOut}).Write(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

// Generator renders the catalogue as indented JSON.
type Generator struct {
	Out   string
	TSOut string
}

// Write builds and writes the catalogue.
func (g Generator) Write() error {
	c := catalog.Builder{Registries: compile.DefaultRegistries()}.Build()
	b, err := json.MarshalIndent(c, "", "  ")
	if err != nil {
		return err
	}
	if err := os.WriteFile(g.Out, append(b, '\n'), FileMode); err != nil {
		return err
	}
	if g.TSOut == "" {
		return nil
	}
	ts := string(TSBanner) + string(b) + ";\n"
	return os.WriteFile(g.TSOut, []byte(ts), FileMode)
}
